// Converts .cdf files into the old MetaboliteDetector 3.3 raw-data cache (<run>.bin + <run>.idx)
// with the old binary's own importer. See make-cache.sh for how it is used.
//
// Loaded with LD_PRELOAD into the old binary: it replaces main() and calls
// CdfImporter(cdf).importData(stem) per file, as the GUI does on NetCDF import.
// Function addresses come from syms.inc, generated by make-cache.sh from `nm`.
#include <dlfcn.h>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>

namespace {

uintptr_t base;

template <class F> F fn(uintptr_t addr) { return reinterpret_cast<F>(base + addr); }

#define SYM(name, addr) constexpr uintptr_t name = addr;
#include "syms.inc"
#undef SYM

// argv: app out_dir cdf...
int import_main(int argc, char** argv, char**) {
    for (int i = 2; i < argc; ++i) {
        const char* cdf = argv[i];
        std::string name = std::strrchr(cdf, '/') ? std::strrchr(cdf, '/') + 1 : cdf;
        std::string stem = std::string(argv[1]) + "/" + name.substr(0, name.rfind('.'));
        alignas(16) static char importer[1 << 16];
        fn<void (*)(void*, const char*)>(CDF_IMPORTER_CTOR)(importer, cdf);
        fn<void (*)(void*, const char*)>(CDF_IMPORT_DATA)(importer, stem.c_str());
        fn<void (*)(void*)>(CDF_IMPORTER_DTOR)(importer);
        std::printf("%s.bin\n", stem.c_str());
    }
    return 0;
}

}  // namespace

extern "C" int __libc_start_main(int (*main)(int, char**, char**), int argc, char** argv, void (*init)(),
                                 void (*fini)(), void (*rtld_fini)(), void* stack_end) {
    base = reinterpret_cast<uintptr_t>(main) - MAIN;
    using Start = int (*)(int (*)(int, char**, char**), int, char**, void (*)(), void (*)(), void (*)(), void*);
    auto real = reinterpret_cast<Start>(dlsym(RTLD_NEXT, "__libc_start_main"));
    return real(import_main, argc, argv, init, fini, rtld_fini, stack_end);
}
